import itertools
import math

def get_divisors(m):
    divs = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.append(i)
            if i * i != m:
                divs.append(m // i)
    return sorted(divs)

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def check_permutation(divisors):
    # Check all permutations of the divisors
    for p in itertools.permutations(divisors):
        prefix_sums = []
        current_sum = 0
        is_success = True
        for divisor in p:
            current_sum += divisor
            prefix_sums.append(current_sum)
            if not is_perfect_square(current_sum):
                is_success = False
                break

        if is_success:
            return True # Found a successful permutation
    return False

results = {}
for m in range(2, 13):
    divisors = get_divisors(m)
    found = check_permutation(divisors)
    results[m] = {
        "divisors": divisors,
        "success": found
    }

print("--- Results ---")
for m, data in results.items():
    print(f"m = {m}: Divisors = {data['divisors']}, Success = {data['success']}")

# Collect successful m values
successful_m = [m for m, data in results.items() if data['success']]
print("\nSuccessful m values found: ", successful_m)

import math
from collections import deque

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def sum_divisors(divs):
    return sum(divs)

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def solve_permutation(m):
    divisors = get_divisors(m)
    n = len(divisors)
    target_sum = sum_divisors(divisors)

    if not is_square(target_sum):
        return False, None

    # We use DFS/backtracking to search for the permutation

    # Optimization: Only start with divisors that are perfect squares
    initial_choices = [d for d in divisors if is_square(d)]

    if not initial_choices and n > 0:
        return False, None

    # Stack stores tuples: (current_sum, used_mask, sequence)
    # Using a mask is efficient for small sets of divisors.

    # Map divisors to indices for mask tracking
    divisor_to_index = {d: i for i, d in enumerate(divisors)}

    # Queue for BFS/State exploration. Since we are looking for *existence*, BFS is clean.
    # State: (current_sum, used_mask)
    queue = deque()

    for initial_d in initial_choices:
        initial_mask = 1 << divisor_to_index[initial_d]
        initial_sum = initial_d

        if is_square(initial_sum):
            # State includes the sum and the used mask
            queue.append((initial_sum, initial_mask))


    while queue:
        current_sum, used_mask = queue.popleft()

        if used_mask == (1 << n) - 1:
            # All divisors used. Since target_sum is checked earlier, this is a success.
            # We found the permutation path implicitly.
            return True, current_sum

        for i in range(n):
            # Check if divisor i is unused
            if not (used_mask & (1 << i)):
                next_d = divisors[i]
                next_sum = current_sum + next_d

                if is_square(next_sum):
                    next_mask = used_mask | (1 << i)
                    queue.append((next_sum, next_mask))

    return False, None

# Candidates provided by the coordinator
candidates = [22, 66, 70, 81, 94, 130]
results = {}

print("--- Running Checks ---")
for m in candidates:
    success, _ = solve_permutation(m)
    results[m] = success
    print(f"m={m}: {'SUCCESS' if success else 'FAIL'}")

print("\n--- Summary ---")
print(results)

def sum_of_divisors(m):
    s = 0
    for i in range(1, int(m**0.5) + 1):
        if m % i == 0:
            s += i
            j = m // i
            if i != j:
                s += j
    return s

